    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver == address(this));
        require(amount > 0);
        require(address(this).balance >= amount);
        require(address(c).balance >= amount);
        uint balBefore = address(this).balance;
        c.sendTo(receiver, amount); if (__ESBMC_reverted()) return;
        uint balAfter = address(this).balance;
        assert(balAfter == balBefore + amount && address(c).balance >= 0);
    }
    receive() external payable {}
}

