// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        receiver = address(this);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(address(c).balance >= amount);
        uint balBefore = address(this).balance;
        try c.sendTo(receiver, amount) {} catch { return; }
        uint balAfter = address(this).balance;
        assertTrue(balAfter == balBefore + amount && address(c).balance >= 0);
    }

    function testFuzz_run(address receiver, uint256 amount) public {
        _run(receiver, amount);
    }

    receive() external payable {}
}
